/**
 * Typed lookup for bundled Jinni phrase audio.
 *
 * Source of truth is phraseRegistry.generated.ts (regenerated by
 * scripts/generate-jinni-phrase-registry.js from the real files under
 * assets/audio/jinni/hi-IN/ — see that script and phraseAudioMap.json
 * for how to add a new phrase).
 *
 * A phrase can have several bundled clips (e.g. 8 different "thinking"
 * lines) — getPhraseAudioAsset picks one at random each call so a
 * frequently-repeated phrase doesn't sound identical every time.
 */
import type { PhraseKey } from '../jinniPhrases';
import { PHRASE_AUDIO_REGISTRY } from './phraseRegistry.generated';

/**
 * Returns a bundled asset module id (what expo-audio's createAudioPlayer
 * expects) for a phrase, randomly chosen if several are registered, or
 * null if no WAV has been registered for it yet. Callers MUST treat
 * null as "skip playback safely" (Prompt.txt A.4) — never throw.
 */
export function getPhraseAudioAsset(id: PhraseKey): number | null {
  const options = PHRASE_AUDIO_REGISTRY[id];
  if (!options || options.length === 0) return null;
  if (options.length === 1) return options[0];
  return options[Math.floor(Math.random() * options.length)];
}

export function hasPhraseAudio(id: PhraseKey): boolean {
  return (PHRASE_AUDIO_REGISTRY[id]?.length ?? 0) > 0;
}

export default getPhraseAudioAsset;
